import os
from taf.ul.sc.perf.reports.benchmark.table import Table
from taf.ul.sc.perf.reports.benchmark.chart import Chart


class Sheet:

    _settings = {
        'cell_format': {
            'font_size': 15
        },
        'device_format': {
            'bold': True,
            'font_color': 'red',
            'font_size': 30
        },
        'index_tab_color': 'blue',
        'chart_tab_color': 'green',
        'table_tab_color': 'yellow'
    }

    def __init__(self, workbook, systime, parsed_data, sheet_name):
        self.sheet_name = sheet_name
        self.workbook = workbook
        self.systime = systime
        self.parsed_data = parsed_data
        self.worksheet = self.workbook.add_worksheet(sheet_name)

        self._charts = None
        self._is_nested = None

    @property
    def is_nested(self):
        return self._is_nested

    @property
    def charts(self):
        return self._charts

    def set_charts(self, charts):
        self._charts = charts

    def generate(self, is_nested=None):
        """
        Using worksheet name generate appropriate sheet with index, chart or table.
        :param is_nested: Optional parameter, inform if dictionary with data is nested.
        """
        if 'table' in self.sheet_name:
            self._generate_table()
        elif 'chart' in self.sheet_name:
            self._generate_chart(is_nested)
        elif self.sheet_name == 'index':
            self._generate_index()

    def _generate_chart_data(self, rows_amount, columns, is_nested_dictionary):
        """
        Generate data needed to draw chart in format: ['table name', first row, first column, last row, last column]
        :param: rows_amount: Number of rows in table.
        :param: columns: If data is nested it is array with last numbers of columns for each separate chart.
                        If data is not nested, it is number of last column in table.
        :param: is_nested_dictionary: Inform if data is nested.
        """
        if is_nested_dictionary:
            self._charts = []
            row_first = 2
            row_last = rows_amount
            column_first = 1
            for column in columns:
                chart_list = [self.sheet_name, row_first, column_first, row_last, column]
                self._charts.append(chart_list)
                column_first = column + 1
        else:
            self._charts = [self.sheet_name, 1, 1, rows_amount, columns + 1]

    def _generate_table(self):
        """
        Format worksheet, create and write data into table, generate data to draw chart.
        """
        self.worksheet.set_tab_color(Sheet._settings['table_tab_color'])
        table = Table(self.worksheet, self.systime, self.parsed_data).write_table()
        values = table.values
        rows_amount = table.rows_amount
        self._is_nested = table.is_nested_dictionary
        self._generate_chart_data(rows_amount, values, self._is_nested)

    def _generate_chart(self, is_nested=None):
        """
        Format worksheet and draw chart.
        :param: is_nested: Optional parameter, inform if dictionary with data is nested.
        """
        self.worksheet.set_tab_color(Sheet._settings['chart_tab_color'])
        Chart(self.workbook, self.worksheet, self._charts, is_nested).draw()

    def _generate_index(self):
        """
        Format worksheet with index, create arrays with sheets and add all sheets with tables and charts to index.
        """
        cell_format = self.workbook.add_format(Sheet._settings['cell_format'])
        device_format = self.workbook.add_format(Sheet._settings['device_format'])
        self.worksheet.set_first_sheet()
        self.worksheet.set_tab_color(Sheet._settings['index_tab_color'])
        device = os.path.basename(self.workbook.filename).replace('.xlsx', '')
        self.worksheet.set_row(1, 35)
        self.worksheet.write(1, 1, device, device_format)
        chart_worksheet = [worksheet for worksheet in self.workbook.sheetnames if 'chart' in worksheet]
        self._add_chart_to_index(chart_worksheet, cell_format)
        table_worksheet = [worksheet for worksheet in self.workbook.sheetnames if 'table' in worksheet]
        self._add_table_to_index(table_worksheet, cell_format)

    def _add_chart_to_index(self, worksheets, cell_format):
        """
        Add all urls of chart sheets to index in given position.
        :param: worksheets: Array with all sheets containing charts.
        :param: cell_format: Workbook format. e.g. containing font_size, font_color.
        """
        row = 3
        start = 1
        worksheets.sort()
        for sheet in worksheets:
            self.worksheet.set_row(row, 20)
            self.worksheet.write_url(row, start, 'internal:' + sheet + '!A1', string=sheet,
                                     cell_format=cell_format)
            row += 1

    def _add_table_to_index(self, worksheets, cell_format):
        """
        Add all urls of table sheets to index in given position.
        :param: worksheets: Array with all sheets containing tables.
        :param: cell_format: Workbook format. e.g. containing font_size.
        """
        row = 3
        start = 6
        worksheets.sort()
        for sheet in worksheets:
            self.worksheet.set_row(row, 20)
            self.worksheet.write_url(row, start, 'internal:' + sheet + '!A1', string=sheet,
                                     cell_format=cell_format)
            row += 1
